Q: Unpredictable opacity behaviour in WPF fonts A: <p>The question is quite old, but I can still add some info here.</p>
<p>This happens because WPF's text rendering pipeline handles brush alpha differently from element-level opacity. ClearType anti-aliasing interacts with alpha blending in a way that produces incorrect visual results, varying by font size.</p>
<p>As <a href="https://stackoverflow.com/users/363224/marnix">Marnix</a> already mentioned, to fix this problem move the alpha channel from the brush to <code>UIElement.Opacity</code>, which goes through a different compositing path and renders correctly.</p>
<p>Here's an attached behavior I've created that does this automatically:</p>
<pre class="lang-cs prettyprint-override"><code>using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

public static class TextAlphaChannelBehavior
{
    public static readonly DependencyProperty UseElementOpacityProperty = DependencyProperty.RegisterAttached(
        &quot;UseElementOpacity&quot;, typeof(bool), typeof(TextAlphaChannelBehavior), new PropertyMetadata(OnUseElementOpacityChanged));

    public static void SetUseElementOpacity(DependencyObject element, bool value) =&gt;
        element.SetValue(UseElementOpacityProperty, value);

    public static bool GetUseElementOpacity(DependencyObject element) =&gt;
        (bool)element.GetValue(UseElementOpacityProperty);

    private static void OnUseElementOpacityChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        if (d is not TextBlock)
        {
            return;
        }

        if (e.NewValue is true)
        {
            d.AddPropertyChanged(TextBlock.ForegroundProperty, OnForegroundChanged);
        }
        else
        {
            d.RemovePropertyChanged(TextBlock.ForegroundProperty, OnForegroundChanged);
        }
    }

    private static void OnForegroundChanged(object sender, DependencyPropertyChangedEventArgs e)
    {
        var textBlock = (TextBlock)sender;

        if (e.NewValue is not SolidColorBrush brush)
        {
            return;
        }

        var color = brush.Color;

        if (color.A == 255)
        {
            return;
        }

        // Move alpha channel to Opacity property
        var opacity = (double)color.A / 255;
        textBlock.SetCurrentValue(UIElement.OpacityProperty, opacity);

        // Remove the alpha channel from the original color
        var opaqueColor = new Color
        {
            R = color.R,
            G = color.G,
            B = color.B,
            A = 255,
        };

        var opaqueBrush = new SolidColorBrush(opaqueColor);

        if (brush.IsFrozen)
        {
            opaqueBrush.Freeze();
        }

        textBlock.SetCurrentValue(TextBlock.ForegroundProperty, opaqueBrush);
    }
}
</code></pre>
<p>The behavior uses a binding-based property change watcher to avoid using built-in <code>DependencyPropertyDescriptor.AddValueChanged</code> which may produce memory leaks:</p>
<pre class="lang-cs prettyprint-override"><code>using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Runtime.CompilerServices;
using System.Windows;
using System.Windows.Data;

public static class DependencyPropertyChangeExtensions
{
    private static readonly ConditionalWeakTable&lt;DependencyObject, Dictionary&lt;DependencyPropertyWatcherKey, DependencyPropertyWatcher&gt;&gt; ObjectWatchers =
        new ConditionalWeakTable&lt;DependencyObject, Dictionary&lt;DependencyPropertyWatcherKey, DependencyPropertyWatcher&gt;&gt;();

    public static void AddPropertyChanged(
        this DependencyObject target,
        DependencyProperty property,
        DependencyPropertyChangedEventHandler handler)
    {
        if (target == null) throw new ArgumentNullException(nameof(target));
        if (property == null) throw new ArgumentNullException(nameof(property));
        if (handler == null) throw new ArgumentNullException(nameof(handler));

        target.Dispatcher.VerifyAccess();

        var watcher = new DependencyPropertyWatcher(target, property, handler);
        var watcherKey = new DependencyPropertyWatcherKey(target, property, handler);

        var propertyWatchers = ObjectWatchers.GetOrCreateValue(target);

        if (!propertyWatchers.TryAdd(watcherKey, watcher))
        {
            // Subscribing twice with the same target, property, and handler is not supported for simplicity.
            watcher.Dispose();
        }
    }

    public static void RemovePropertyChanged(
        this DependencyObject target,
        DependencyProperty property,
        DependencyPropertyChangedEventHandler handler)
    {
        if (target == null) throw new ArgumentNullException(nameof(target));
        if (property == null) throw new ArgumentNullException(nameof(property));
        if (handler == null) throw new ArgumentNullException(nameof(handler));

        target.Dispatcher.VerifyAccess();

        var watcherKey = new DependencyPropertyWatcherKey(target, property, handler);

        if (ObjectWatchers.TryGetValue(target, out var propertyWatchers) &amp;&amp;
            propertyWatchers.TryGetValue(watcherKey, out var watcher))
        {
            watcher.Dispose();
            propertyWatchers.Remove(watcherKey);

            if (propertyWatchers.Count == 0)
            {
                ObjectWatchers.Remove(target);
            }
        }
    }

    private record DependencyPropertyWatcherKey(
        DependencyObject Target,
        DependencyProperty Property,
        DependencyPropertyChangedEventHandler Handler);

    private class DependencyPropertyWatcher : DependencyObject, IDisposable
    {
        private readonly DependencyObject _target;

        private DependencyPropertyChangedEventHandler _handler;

        public DependencyPropertyWatcher(
            DependencyObject target,
            DependencyProperty property,
            DependencyPropertyChangedEventHandler handler)
        {
            _target = target;
            _handler = handler;

            var binding = new Binding
            {
                Source = target,
                Path = new PropertyPath(property.Name),
                Mode = BindingMode.OneWay,
            };

            BindingOperations.SetBinding(this, ValueProperty, binding);
        }

        private static readonly DependencyProperty ValueProperty = DependencyProperty.Register(
            &quot;Value&quot;,
            typeof(object),
            typeof(DependencyPropertyWatcher),
            new PropertyMetadata(OnValueChanged));

        private static void OnValueChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
        {
            var watcher = (DependencyPropertyWatcher)d;

            watcher.OnValueChanged(e);
        }

        private void OnValueChanged(DependencyPropertyChangedEventArgs e)
        {
            _handler?.Invoke(_target, e);
        }

        public void Dispose()
        {
            _handler = null;
            BindingOperations.ClearBinding(this, ValueProperty);
        }
    }
}
</code></pre>
<p>Usage:</p>
<pre class="lang-xml prettyprint-override"><code>&lt;TextBlock Text=&quot;Sample&quot;
           Foreground=&quot;#80000000&quot;
           behaviors:TextAlphaChannelBehavior.UseElementOpacity=&quot;True&quot; /&gt;
</code></pre>
<p>You can also set it through the Style globally. But keep in mind that it may cost some memory (not much really).</p>

Q: Append instances of specific word in string with incrementing integer A: <p>i don't know why you need this but here is a solution</p>
<pre><code>&lt;?php
$var=&quot;THIS&quot;;
$string=&quot;
Lorem ipsum THIS dolor sit THIS amet, consectetur THIS adipiscing elit.
&quot;
$array=explode($var,$string);
for($i=0;$i&lt;count($array)-1;$i++){
$array[$i]=$array[$i].&quot; THIS&quot;.$i+1;

};
$string=implode(&quot;&quot;,$array);
echo $string;
?&gt;
</code></pre>
